package com.example.techfix;
import android.Manifest; import android.content.pm.PackageManager; import android.os.*; import android.widget.*; import androidx.activity.result.ActivityResultLauncher; import androidx.activity.result.contract.ActivityResultContracts; import androidx.appcompat.app.AppCompatActivity; import androidx.core.content.ContextCompat; import com.example.techfix.data.AppDatabase; import com.example.techfix.data.entity.*; import com.example.techfix.util.LocationUtils; import com.google.android.gms.location.*; import java.util.*; import java.util.concurrent.*;
public class BookingActivity extends AppCompatActivity {private AppDatabase db;private int serviceId,customerId;private Branch nearestBranch;private final ExecutorService executor=Executors.newSingleThreadExecutor();private final Handler main=new Handler(Looper.getMainLooper());private ActivityResultLauncher<String> locationPermissionLauncher;
 @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_booking);db=AppDatabase.getDatabase(getApplicationContext());serviceId=getIntent().getIntExtra("SERVICE_ID",-1);customerId=getIntent().getIntExtra("CUSTOMER_ID",-1);String name=getIntent().getStringExtra("SERVICE_NAME");double price=getIntent().getDoubleExtra("SERVICE_PRICE",0);((TextView)findViewById(R.id.tvServiceName)).setText(name==null?"":name);((TextView)findViewById(R.id.tvServicePrice)).setText(String.format("Rs. %.2f",price));locationPermissionLauncher=registerForActivityResult(new ActivityResultContracts.RequestPermission(),granted->{if(granted)fetchLocationAndFindBranch();else Toast.makeText(this,"Location permission is required to find the nearest branch",Toast.LENGTH_LONG).show();});findViewById(R.id.btnFindBranch).setOnClickListener(v->checkPermissionAndFetchLocation());findViewById(R.id.btnConfirmBooking).setOnClickListener(v->confirmBooking());}
 private void checkPermissionAndFetchLocation(){if(ContextCompat.checkSelfPermission(this,Manifest.permission.ACCESS_FINE_LOCATION)==PackageManager.PERMISSION_GRANTED)fetchLocationAndFindBranch();else locationPermissionLauncher.launch(Manifest.permission.ACCESS_FINE_LOCATION);}
 private void fetchLocationAndFindBranch(){TextView status=findViewById(R.id.tvBranchStatus);status.setText("Getting your location...");FusedLocationProviderClient client=LocationServices.getFusedLocationProviderClient(this);try{client.getCurrentLocation(Priority.PRIORITY_HIGH_ACCURACY,new CancellationTokenSource().getToken()).addOnSuccessListener(location->{if(location==null){status.setText("Couldn't get location. Make sure GPS is enabled and try again.");return;}executor.execute(()->{List<Branch> branches=db.branchDao().getAllBranches();if(branches.isEmpty()){main.post(()->status.setText("No branches available."));return;}Branch closest=null;double best=Double.MAX_VALUE;for(Branch br:branches){double d=LocationUtils.distanceKm(location.getLatitude(),location.getLongitude(),br.getLatitude(),br.getLongitude());if(d<best){best=d;closest=br;}}final Branch selected=closest;final double distance=best;nearestBranch=selected;main.post(()->{status.setText(String.format("Nearest branch: %s (%.1f km away)",selected.getName(),distance));findViewById(R.id.btnConfirmBooking).setEnabled(true);});});}).addOnFailureListener(e->status.setText("Failed to get location: "+e.getMessage()));}catch(SecurityException e){status.setText("Location permission error. Please try again.");}}
 private void confirmBooking(){String date=((EditText)findViewById(R.id.etDate)).getText().toString().trim();if(date.isEmpty()){Toast.makeText(this,"Please enter a preferred date",Toast.LENGTH_SHORT).show();return;}if(nearestBranch==null){Toast.makeText(this,"Please find your nearest branch first",Toast.LENGTH_SHORT).show();return;}final Branch br=nearestBranch;executor.execute(()->{db.appointmentDao().insertAppointment(new Appointment(customerId,br.getBranchId(),serviceId,date,"Pending"));main.post(()->{Toast.makeText(this,"Appointment booked at "+br.getName()+"!",Toast.LENGTH_LONG).show();finish();});});}
 @Override protected void onDestroy(){executor.shutdown();super.onDestroy();}}
